.ds-sorbet { --ds-cover-bg: var(--ds-cream); --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-strawberry); --ds-hand-fill2: var(--ds-blueberry); --ds-hand-muted: var(--ds-lilac); --ds-hand-ground: var(--ds-cream-raised); --ds-hand-stroke: 3; --ds-hand-cap: round; --ds-hand-shadow: var(--ds-ink); --ds-hand-bg: var(--ds-cream-sunk);
  --ds-tpl-edge: 3px solid var(--ds-ink); --ds-tpl-radius: 20px; --ds-tpl-rule: 3px solid var(--ds-ink); --ds-tpl-tile-shadow: var(--ds-drop); --ds-tpl-shadow: none; --ds-slide-bg: var(--ds-cream-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-strawberry); --ds-slide-title-fg: var(--ds-on-strawberry); --ds-slide-split-a: var(--ds-strawberry); --ds-slide-split-a-fg: var(--ds-on-strawberry); --ds-slide-split-b: var(--ds-blueberry); --ds-slide-split-b-fg: var(--ds-on-blueberry); --ds-hero-bg: var(--ds-cream-sunk); --ds-tag-radius: 999px; }
.ds-sorbet .ds-section h2, .ds-sorbet .ds-cover-name { font-family: var(--font-display); font-weight: 700; letter-spacing: -.01em; }
.ds-sorbet .ds-eyebrow, .ds-sorbet .ds-chip { font-family: var(--font-display); font-weight: 600; } .ds-sorbet .ds-chip { border-radius: 999px; border-width: 2px; opacity: 1; }
.ds-sorbet .h-num { font-family: var(--font-display); font-weight: 700; } .ds-sorbet .h-plate, .ds-sorbet .h-text { font-family: var(--font-mono); }
.ds-sorbet .sb-cream { fill: var(--ds-cream); }
.ds-sorbet .sb-f-straw { fill: var(--ds-strawberry); background: var(--ds-strawberry); } .ds-sorbet .sb-f-mango { fill: var(--ds-mango); background: var(--ds-mango); } .ds-sorbet .sb-f-lime { fill: var(--ds-lime); background: var(--ds-lime); } .ds-sorbet .sb-f-blue { fill: var(--ds-blueberry); background: var(--ds-blueberry); } .ds-sorbet .sb-f-grape { fill: var(--ds-grape); background: var(--ds-grape); }
.ds-sorbet .sb-shadow { fill: var(--ds-hand-ink); stroke: var(--ds-hand-ink); stroke-width: 3; stroke-linejoin: round; } .ds-sorbet .sb-rim { fill: var(--ds-rim); stroke: var(--ds-rim); stroke-width: 9; stroke-linejoin: round; } .ds-sorbet .sb-outline { stroke: var(--ds-hand-ink); stroke-width: 3; stroke-linejoin: round; }
.ds-sorbet .sb-wave { fill: none; stroke: var(--ds-hand-ink); stroke-width: 3; stroke-linecap: round; }
.ds-sorbet .sb-sticker-t { font-family: var(--font-display); font-weight: 700; font-size: 16px; letter-spacing: .06em; fill: var(--ds-hand-ink); } .ds-sorbet .sb-on-blue { fill: var(--ds-on-blueberry); color: var(--ds-on-blueberry); }
.ds-sorbet .sb-cover-word { font-family: var(--font-display); font-weight: 700; font-size: 72px; fill: var(--ds-hand-ink); } .ds-sorbet .sb-blob-t { font-family: var(--font-display); font-weight: 600; font-size: 22px; fill: var(--ds-hand-ink); } .ds-sorbet .sb-blob-n { font-family: var(--font-display); font-weight: 700; font-size: 64px; letter-spacing: -.02em; fill: var(--ds-hand-ink); }
.ds-sorbet .sb-muted { color: var(--ds-ink-muted); } .ds-sorbet .sb-word { color: var(--ds-strawberry); }
.ds-sorbet .sb-sticker { border: 3px solid var(--ds-ink); border-radius: 20px; background: var(--ds-cream-raised); box-shadow: var(--ds-sticker); }
.ds-sorbet .sb-btn { font-family: var(--font-display); font-size: 16px; font-weight: 600; line-height: 20px; padding: 11px 22px; border: 3px solid var(--ds-ink); border-radius: 999px; background: var(--ds-cream-raised); color: var(--ds-ink); box-shadow: var(--ds-drop); cursor: pointer; transition: transform 160ms var(--ds-spring), box-shadow 160ms var(--ds-spring); }
.ds-sorbet .sb-btn:hover { transform: scale(1.03); } .ds-sorbet .sb-btn:active { transform: translateY(4px); box-shadow: 2px 2px 0 0 var(--ds-ink); } .ds-sorbet .sb-btn:focus-visible { outline: 3px solid var(--ds-blueberry); outline-offset: 3px; }
.ds-sorbet .sb-btn-primary { background: var(--ds-strawberry); color: var(--ds-on-strawberry); } .ds-sorbet .sb-btn-mango { background: var(--ds-mango); } .ds-sorbet .sb-btn-sm { padding: 7px 16px; font-size: 14px; }
.ds-sorbet .sb-tag { display: inline-flex; align-items: center; padding: 3px 12px; border: 2px solid var(--ds-ink); border-radius: 999px; font-family: var(--font-display); font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; background: var(--ds-cream-raised); color: var(--ds-ink); line-height: 16px; }
.ds-sorbet .sb-tag-straw { background: var(--ds-strawberry); } .ds-sorbet .sb-tag-blue { background: var(--ds-blueberry); color: var(--ds-on-blueberry); } .ds-sorbet .sb-tag-mango { background: var(--ds-mango); } .ds-sorbet .sb-tag-lime { background: var(--ds-lime); }
.ds-sorbet .sb-sticker-chip { display: inline-flex; padding: 5px 14px; border: 3px solid var(--ds-ink); border-radius: 999px; background: var(--ds-mango); color: var(--ds-ink); font-family: var(--font-display); font-weight: 700; font-size: 14px; letter-spacing: .04em; box-shadow: var(--ds-sticker); transform: rotate(-6deg); }
.ds-sorbet .ds-tpl-tag { border: 2px solid var(--ds-ink); font-family: var(--font-display); } .ds-sorbet .ds-tpl-tag.is-ok { background: var(--ds-lime); color: var(--ds-ink); } .ds-sorbet .ds-tpl-tag.is-warn { background: var(--ds-mango); color: var(--ds-ink); } .ds-sorbet .ds-tpl-tag.is-bad { background: var(--ds-strawberry); color: var(--ds-ink); } .ds-sorbet .ds-tpl-tag.is-idle { background: var(--ds-lilac); }
.ds-sorbet .sb-stat { display: grid; gap: 6px; padding: 18px 22px; min-width: 190px; } .ds-sorbet .sb-stat-mango { background: var(--ds-mango); color: var(--ds-ink); } .ds-sorbet .sb-stat-mango .t-label, .ds-sorbet .sb-stat-mango .sb-small { color: var(--ds-ink); }
.ds-sorbet .sb-scoops { display: flex; margin-top: 4px; } .ds-sorbet .sb-scoop { display: inline-block; width: 28px; height: 28px; border-radius: 999px; border: 3px solid var(--ds-ink); margin-right: -8px; }
.ds-sorbet .sb-small { font-family: var(--font-body); font-size: 13px; color: var(--ds-ink-muted); line-height: 1.4; } .ds-sorbet .ds-stats { gap: 24px; }
.ds-sorbet .sb-bubble { position: relative; padding: 14px 20px; border: 3px solid var(--ds-ink); border-radius: 20px; background: var(--ds-cream-raised); box-shadow: var(--ds-sticker); font-size: 15px; line-height: 1.4; margin-bottom: 8px; } .ds-sorbet .sb-bubble strong { font-family: var(--font-display); font-weight: 600; }
.ds-sorbet .sb-bubble::after { content: ""; position: absolute; left: 28px; bottom: -14px; width: 20px; height: 20px; background: inherit; border-right: 3px solid var(--ds-ink); border-bottom: 3px solid var(--ds-ink); transform: rotate(45deg) skew(10deg, 10deg); }
.ds-sorbet .sb-bubble-lime { background: var(--ds-lime); } .ds-sorbet .sb-bubble-mango { background: var(--ds-mango); } .ds-sorbet .sb-bubble-straw { background: var(--ds-strawberry); } .ds-sorbet .ds-callouts { gap: 20px; }
.ds-sorbet .sb-dot { display: inline-block; width: 40px; height: 40px; border-radius: 999px; border: 3px solid var(--ds-ink); }
.ds-sorbet .sb-card { position: relative; padding: 24px; display: grid; gap: 6px; } .ds-sorbet .sb-card-chip { position: absolute; top: -14px; right: 18px; } .ds-sorbet .sb-card h3 { margin: 0; } .ds-sorbet .sb-card-p { margin: 4px 0 8px; line-height: 1.5; color: var(--ds-ink-muted); max-width: 52ch; }
.ds-sorbet .sb-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between; } .ds-sorbet .sb-row-start { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 24px; }
.ds-sorbet .sb-sample { background: var(--ds-cream); padding: 24px 20px 48px; } .ds-sorbet .sb-sample-in { max-width: 1100px; margin: 0 auto; }
.ds-sorbet .sb-sample-top { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px; } .ds-sorbet .sb-brand { font-size: 32px; }
.ds-sorbet .sb-hero { display: grid; gap: 32px; margin-top: 28px; align-items: center; } .ds-sorbet .sb-hero-chip { margin-bottom: 20px; } .ds-sorbet .sb-sample-h { margin: 0; max-width: 11ch; } .ds-sorbet .sb-sample-lede { margin-top: 16px; max-width: 42ch; }
.ds-sorbet .sb-hero-art svg { display: block; width: min(100%, 360px); height: auto; margin: 0 auto; }
.ds-sorbet .sb-stalls { display: grid; gap: 24px; margin-top: 40px; } .ds-sorbet .sb-stall { display: grid; grid-template-columns: 40px 1fr auto; gap: 14px; align-items: center; padding: 14px 18px; } .ds-sorbet .sb-stall div { display: grid; }
.ds-sorbet .sb-sample-bottom { display: grid; gap: 24px; margin-top: 40px; } .ds-sorbet .sb-panel { padding: 16px 20px; min-width: 0; } .ds-sorbet .sb-panel .t-label { display: block; margin-bottom: 10px; }
.ds-sorbet .sb-center { display: block; text-align: center; margin-top: 28px; }
.ds-sorbet .ds-tpl-kpi, .ds-sorbet .ds-tpl-tile, .ds-sorbet .ds-tpl-step { box-shadow: var(--ds-drop); } .ds-sorbet .ds-tpl-figure { box-shadow: var(--ds-drop); }
.ds-sorbet .ds-tpl-stage-title .ds-tpl-stage-foot { border-top-width: 3px; }
@container (min-width: 760px) { .ds-sorbet .sb-sample { padding: 32px 40px 64px; } .ds-sorbet .sb-hero { grid-template-columns: 3fr 2fr; } .ds-sorbet .sb-stalls { grid-template-columns: 1fr 1fr 1fr; } .ds-sorbet .sb-sample-bottom { grid-template-columns: 1fr 1fr; } }
